"""Source and skeleton indexes. No application code is executed."""
from collections import defaultdict
from pathlib import Path
import re
import json
import warnings

from tree_sitter import Language, Parser
import tree_sitter_java
from baseline_closure import Index, load_json, RouteWarning
from .state import U
from .models import date_value


def text(node):
    return node.text.decode('utf-8') if node is not None else ''


def walk(node):
    yield node
    for child in node.named_children:
        yield from walk(child)


class Project:
    def __init__(self, skeleton, root):
        self.skeleton = load_json(str(skeleton))
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter('always', RouteWarning)
            self.ix = Index(self.skeleton)
        self.route_warnings = list(dict.fromkeys(str(item.message) for item in caught))
        self.nodes = self.ix.N
        self.root = Path(root)
        self.methods = {k: v for k, v in self.nodes.items() if v['kind'] == 'method'}
        self.by_name = defaultdict(list)
        self.trees, self.sources, self.ast, self.source_errors = {}, {}, {}, []
        self.edges = defaultdict(lambda: defaultdict(set))
        self.sites = defaultdict(list)
        self.by_line = defaultdict(list)
        self.enums = {}
        self.enum_objects = {}
        type_names = defaultdict(list)
        qualified_types = defaultdict(list)
        for tid, node in self.nodes.items():
            if node['kind'] == 'type':
                type_names[node['fqn'].split('.')[-1]].append(tid)
                qualified_types[node['fqn']].append(tid)
        self.enum_prefixes = {tid: (tid if len(qualified_types[node['fqn']]) > 1 else node['fqn'] if len(type_names[node['fqn'].split('.')[-1]]) > 1 else node['fqn'].split('.')[-1])
                              for tid, node in self.nodes.items() if node['kind'] == 'type'}
        self.builder_types = {}
        self.all_args_types = {}
        self.constants = {}
        parser = Parser(Language(tree_sitter_java.language()))
        for mid, method in self.methods.items():
            self.by_name[method['name']].append(mid)
            file = method['file']
            if file not in self.trees:
                self.sources[file] = (self.root / file).read_bytes()
                tree = parser.parse(self.sources[file])
                self.trees[file] = tree
                if tree.root_node.has_error:
                    self.source_errors.append(file)
        declarations = {}
        for tid, meta in self.nodes.items():
            if meta['kind'] != 'type' or not meta.get('file', '').endswith('.java'): continue
            file = meta['file']
            tree = self.trees.get(file)
            if tree is None:
                self.sources[file] = (self.root / file).read_bytes()
                tree = parser.parse(self.sources[file])
                self.trees[file] = tree
                if tree.root_node.has_error:
                    self.source_errors.append(file)
            for decl in walk(tree.root_node):
                if decl.type not in ('class_declaration', 'enum_declaration') or text(decl.child_by_field_name('name')) != meta['fqn'].split('.')[-1]: continue
                body = decl.child_by_field_name('body')
                fields = []
                for field in body.named_children if body else []:
                    if field.type != 'field_declaration': continue
                    for var in field.named_children:
                        if var.type != 'variable_declarator': continue
                        name = text(var.child_by_field_name('name'))
                        if re.search(r'\bstatic\b', text(field)):
                            try: self.constants[meta['fqn'].split('.')[-1] + '.' + name] = json.loads(text(var.child_by_field_name('value')))
                            except ValueError: pass
                        else:
                            fields.append((name, text(field.child_by_field_name('type'))))
                modifiers = next((text(c) for c in decl.named_children if c.type == 'modifiers'), '')
                if '@Builder' in modifiers: self.builder_types[meta['fqn']] = fields
                if '@AllArgsConstructor' in modifiers: self.all_args_types[meta['fqn']] = fields
        for file, tree in self.trees.items():
            declarations[file] = [n for n in walk(tree.root_node) if n.type in ('method_declaration', 'constructor_declaration')]
            for node in walk(tree.root_node):
                if node.type == 'enum_declaration':
                    name = text(node.child_by_field_name('name'))
                    owners = [tid for tid in type_names[name] if self.nodes[tid].get('file') == file]
                    if len(owners) != 1:
                        continue
                    enum_tid = owners[0]
                    prefix = self.enum_prefixes[enum_tid]
                    constructors = [n for n in walk(node) if n.type == 'constructor_declaration']
                    for const in walk(node):
                        if const.type == 'enum_constant':
                            args = const.child_by_field_name('arguments')
                            if args and args.named_children:
                                raw = text(args.named_children[0])
                                enum_key = prefix + '.' + text(const.child_by_field_name('name'))
                                if raw.startswith('"'):
                                    self.enum_objects[enum_key] = {'__enum__': enum_key, 'name': json.loads(raw)}
                                if re.fullmatch(r'-?\d+', raw):
                                    self.enums[enum_key] = int(raw)
                                    self.enum_objects[enum_key] = {'__enum__': enum_key, 'code': int(raw)}
                                    if len(args.named_children) > 1 and text(args.named_children[1]).startswith('"'):
                                        self.enum_objects[enum_key]['name'] = json.loads(text(args.named_children[1]))
                                for ctor in constructors:
                                    params = ctor.child_by_field_name('parameters').named_children
                                    if len(params) != len(args.named_children): continue
                                    bindings = {}
                                    for par, arg in zip(params, args.named_children):
                                        try: val = json.loads(text(arg))
                                        except ValueError: val = U
                                        bindings[text(par.child_by_field_name('name'))] = val
                                    obj = {'__enum__': enum_key}
                                    for assignment in walk(ctor):
                                        if assignment.type != 'assignment_expression': continue
                                        lhs = text(assignment.child_by_field_name('left'))
                                        rhs = text(assignment.child_by_field_name('right'))
                                        if lhs.startswith('this.') and rhs in bindings:
                                            obj[lhs[5:]] = bindings[rhs]
                                    self.enum_objects[enum_key] = obj
                                self.enum_objects[enum_key]['__enum_type__'] = enum_tid
        for mid, method in self.methods.items():
            name = method['name'] if method['name'] != '<init>' else self.nodes[method['owner']]['fqn'].split('.')[-1].split('$')[-1]
            matches = [n for n in declarations[method['file']]
                       if text(n.child_by_field_name('name')) == name
                       and n.start_point.row + 1 <= method['line'] <= n.end_point.row + 1
                       and [text(p.child_by_field_name('type')) for p in n.child_by_field_name('parameters').named_children
                            if p.type in ('formal_parameter', 'spread_parameter')]
                           == method.get('params_as_written', [])]
            if matches:
                self.ast[mid] = min(matches, key=lambda n: n.end_byte - n.start_byte)
        for nid, node in self.nodes.items():
            if node['kind'] == 'call_site':
                self.sites[node['method']].append(nid)
                self.by_line[(node['method'], node['line'], node['callee'])].append(nid)
        for edge in self.skeleton['edges']:
            self.edges[edge['source']][edge['type']].add(edge['target'])
        self.repository_queries = {}
        for mid, node in self.ast.items():
            query = re.search(r'@Query\(\s*(?:value\s*=\s*)?"((?:\\.|[^"\\])*)"', text(node), re.S)
            if query:
                owner = self.nodes[self.methods[mid]['owner']]['fqn']
                where = re.search(r'\bwhere\b(.+)', query[1], re.I | re.S)
                predicates = []
                if not re.match(r'\s*(?:select\s+(?:\*|\w+\.?\*)?\s*from|select\s+\w+\s+from|from)\b', query[1], re.I):
                    predicates = None
                elif re.search(r'\b(join|order|group|having|limit|union)\b', query[1], re.I):
                    predicates = None
                elif where:
                    for part in re.split(r'\band\b', where[1], flags=re.I):
                        match = re.fullmatch(r'\s*(?:\w+\.)?(\w+)\s*(=|in)\s*\(?\s*\?(\d+)\s*\)?\s*', part, re.I)
                        if not match:
                            predicates = None
                            break
                        predicates.append(match.groups())
                self.repository_queries[(owner, self.methods[mid]['name'])] = predicates
        self.entities = {}
        self.column_aliases = {}
        self.generated_ids = {}
        self.collections = {}
        for rid, resource in self.nodes.items():
            if resource['kind'] != 'data_resource' or resource.get('collection_of'):
                continue
            files = {o.get('file') for o in resource.get('origin', [])}
            types = [tid for tid, n in self.nodes.items() if n['kind'] == 'type' and n.get('file') in files]
            if len(types) > 1:
                explicit = [tid for tid in types for annotation in self.nodes[tid].get('annotations', [])
                            if annotation['name'].split('.')[-1] == 'Table' and re.search(
                                r'\bname\s*=\s*"' + re.escape(resource['name']) + r'"', annotation.get('args') or '')]
                entities = [tid for tid in types if any(a['name'].split('.')[-1] == 'Entity' for a in self.nodes[tid].get('annotations', []))]
                types = explicit if len(explicit) == 1 else entities
            if len(types) == 1:
                self.entities[rid] = types[0]
            aliases = {}
            collections = []
            for file in sorted(f for f in files if f):
                tree = self.trees.get(file) or parser.parse((self.root / file).read_bytes())
                for field in walk(tree.root_node):
                    if field.type != 'field_declaration': continue
                    collection = re.search(r'@CollectionTable\(\s*name\s*=\s*"([^"]+)".*?@JoinColumn\(\s*name\s*=\s*"([^"]+)"', text(field), re.S)
                    if collection:
                        from .state import camel
                        for var in field.named_children:
                            if var.type == 'variable_declarator':
                                collections.append((text(var.child_by_field_name('name')), collection[1], camel(collection[2])))
                    if '@GeneratedValue' in text(field):
                        for var in field.named_children:
                            if var.type == 'variable_declarator':
                                self.generated_ids[rid] = text(var.child_by_field_name('name'))
                    column = re.search(r'@Column\([^)]*\bname\s*=\s*"([^"]+)"', text(field))
                    if column:
                        from .state import camel
                        for var in field.named_children:
                            if var.type == 'variable_declarator':
                                aliases[camel(column[1])] = text(var.child_by_field_name('name'))
            self.column_aliases[rid] = aliases
            self.collections[rid] = collections
        self.extract_metadata()
        self.extract_element_collections()

    def extract_element_collections(self):
        """Source/skeleton-backed scalar collections, including default JPA names."""
        from .state import camel
        for rid, tid in self.entities.items():
            owner = self.nodes[tid]
            tree = self.trees.get(owner.get('file'))
            keys = self.id_fields.get(rid, [])
            if tree is None or len(keys) != 1:
                continue
            key_column = self.type_fields[tid][keys[0]]['column']
            entity_name = owner['fqn'].split('.')[-1]
            for annotation in owner.get('annotations', []):
                if annotation['name'].split('.')[-1] == 'Entity':
                    explicit = re.search(r'\bname\s*=\s*"([^"]+)"', annotation.get('args') or '')
                    if explicit:
                        entity_name = explicit[1]
            for field in walk(tree.root_node):
                raw = text(field)
                if field.type != 'field_declaration' or '@ElementCollection' not in raw:
                    continue
                typ = text(field.child_by_field_name('type'))
                if not re.fullmatch(r'(?:java\.util\.)?(?:List|Set|Collection)<(?:String|Integer|Long|Double|Float|Boolean)>', typ):
                    continue
                for var in field.named_children:
                    if var.type != 'variable_declarator':
                        continue
                    prop = text(var.child_by_field_name('name'))
                    resources = [n for n in self.nodes.values() if n['kind'] == 'data_resource' and n.get('collection_of') == tid
                                 and any(o.get('file') == owner.get('file') and field.start_point.row + 1 <= o.get('line', 0) <= field.end_point.row + 1
                                         for o in n.get('origin', []))]
                    existing = next((c for c in self.collections.get(rid, []) if c[0] == prop), None)
                    if len(resources) != 1 and existing is None:
                        continue
                    table = resources[0]['name'] if len(resources) == 1 else existing[1]
                    join = re.search(r'@JoinColumn\([^)]*\bname\s*=\s*"([^"]+)"', raw)
                    foreign = camel(join[1] if join else entity_name[:1].lower() + entity_name[1:] + '_' + key_column)
                    column = re.search(r'@Column\([^)]*\bname\s*=\s*"([^"]+)"', raw)
                    value_column = camel(column[1] if column else prop)
                    order = re.search(r'@OrderColumn\b(?:\(([^)]*)\))?', raw)
                    explicit_order = re.search(r'\bname\s*=\s*"([^"]+)"', order[1] or '') if order else None
                    order_column = camel(explicit_order[1] if explicit_order else prop + '_ORDER') if order else None
                    mapping = (prop, table, foreign, value_column, order_column)
                    self.collections[rid] = [c for c in self.collections.get(rid, []) if c[0] != prop] + [mapping]

    def extract_metadata(self):
        """Derive field, enum and datasource contracts from source declarations."""
        self.type_fields, self.enum_members, self.id_fields, self.framework_types = {}, {}, {}, {}
        self.config = [dict(id=i, **n) for i, n in self.nodes.items() if n['kind'] == 'config_entry']
        self.schemas = {}
        self.active_profiles = {'default'}
        for item in self.config:
            if item['key'].endswith('profiles.active'):
                self.active_profiles = set(re.split(r'[,\s]+', str(item['value'])))
            if item['key'].endswith('datasource.url'):
                match = re.search(r'jdbc:[^:]+://[^/]+/([^?;]+)', str(item['value']))
                if match:
                    self.schemas[item['module']] = match[1]
        for tid, meta in self.nodes.items():
            if meta['kind'] != 'type':
                continue
            tree = self.trees.get(meta.get('file'))
            if not tree:
                continue
            declarations = [n for n in walk(tree.root_node)
                            if n.type in ('class_declaration', 'enum_declaration')
                            and text(n.child_by_field_name('name')) == meta['fqn'].split('.')[-1]]
            if not declarations:
                continue
            decl = declarations[0]
            header = text(decl).split('{', 1)[0]
            self.framework_types[tid] = set(re.findall(r'\b(?:implements|extends)\s+([\w.]+)', header))
            if decl.type == 'enum_declaration':
                members = []
                for n in walk(decl):
                    if n.type != 'enum_constant':
                        continue
                    key = self.enum_prefixes[tid] + '.' + text(n.child_by_field_name('name'))
                    self.enum_objects.setdefault(key, {'__enum__': key, '__enum_type__': tid, 'name': key.rsplit('.', 1)[-1]})
                    members.append(key)
                self.enum_members[tid] = members
            fields = {}
            body = decl.child_by_field_name('body')
            for field in body.named_children if body else []:
                if field.type != 'field_declaration' or re.search(r'\bstatic\b', text(field)):
                    continue
                raw = text(field)
                column = re.search(r'@Column\([^)]*\bname\s*=\s*"([^"]+)"', raw)
                for var in field.named_children:
                    if var.type != 'variable_declarator':
                        continue
                    name = text(var.child_by_field_name('name'))
                    value = var.child_by_field_name('value')
                    default = U
                    if value:
                        try:
                            default = json.loads(text(value))
                        except ValueError:
                            pass
                    fields[name] = {'type': text(field.child_by_field_name('type')),
                                    'default': default, 'has_initializer': value is not None,
                                    'column': column[1] if column else name,
                                    'embedded': bool(re.search(r'@Embedded(?:Id)?\b', raw)),
                                    'id': bool(re.search(r'@(?:Id|EmbeddedId)\b', raw)),
                                    'qualifier': (re.search(r'@Qualifier\(\s*"([^"]+)"', raw)[1]
                                                  if re.search(r'@Qualifier\(\s*"([^"]+)"', raw) else None),
                                    'enum_string': 'EnumType.STRING' in raw,
                                    'file': meta['file'], 'line': field.start_point.row + 1}
            self.type_fields[tid] = fields
        for rid, tid in self.entities.items():
            self.id_fields[rid] = [name for name, field in self.type_fields.get(tid, {}).items() if field['id']]

    def enum_reference(self, expression, mid):
        if '.' not in expression or mid not in self.methods:
            return None
        owner, member = expression.rsplit('.', 1)
        meta = self.methods[mid]
        tid = self.resolve_type(owner, meta['module'], meta['file'])
        if tid not in self.enum_members:
            return None
        key = self.enum_prefixes[tid] + '.' + member
        return key if key in self.enum_members[tid] else None

    def resolve_type(self, name, module, file=None):
        written = name.split('<')[0].replace('[]', '').strip()
        name = written.split('.')[-1]
        candidates = [tid for tid, node in self.nodes.items() if node['kind'] == 'type'
                      and node['fqn'].split('.')[-1] == name]
        exact = [tid for tid in candidates if self.nodes[tid]['fqn'] == written]
        if '.' in written and exact:
            local = [tid for tid in exact if self.nodes[tid].get('module') == module]
            return local[0] if len(local) == 1 else exact[0] if len(exact) == 1 else None
        if file and candidates:
            cache = self.__dict__.setdefault('_source_namespaces', {})
            if file not in cache:
                root = self.trees[file].root_node
                package_node = next((n for n in root.named_children if n.type == 'package_declaration'), None)
                package = re.search(r'\bpackage\s+([\w.]+)\s*;', text(package_node))
                imports = [match[1] for node in root.named_children if node.type == 'import_declaration'
                           for match in [re.search(r'\bimport\s+(?!static\b)([\w.*]+)\s*;', text(node))] if match]
                cache[file] = (package[1] if package else '', imports)
            package, imports = cache[file]
            imported = [tid for tid in candidates if self.nodes[tid]['fqn'] in imports]
            if imported:
                return imported[0] if len(imported) == 1 else None
            same_package = [tid for tid in candidates if self.nodes[tid]['fqn'] == package + '.' + name]
            if same_package:
                return same_package[0] if len(same_package) == 1 else None
            wildcard = [tid for tid in candidates if self.nodes[tid]['fqn'].rsplit('.', 1)[0] + '.*' in imports]
            if wildcard:
                return wildcard[0] if len(wildcard) == 1 else None
        same = [tid for tid in candidates if self.nodes[tid].get('module') == module]
        return same[0] if len(same) == 1 else candidates[0] if len(candidates) == 1 else None

    def request_fields(self, mid):
        fields = {}
        for name, typ in self.parameters(mid):
            tid = self.resolve_type(typ, self.methods[mid]['module'])
            nested = self.type_fields.get(tid, {})
            if nested:
                fields.update({key: value['type'] for key, value in nested.items()})
            else:
                fields[name] = typ
        return fields

    def http_parameters(self, mid):
        """Declared HTTP envelopes and aliases; ordinary Java names are preserved."""
        node = self.ast.get(mid)
        pars = node.child_by_field_name('parameters') if node else None
        result = []
        for par in pars.named_children if pars else []:
            if par.type != 'formal_parameter':
                continue
            name = text(par.child_by_field_name('name'))
            typ = text(par.child_by_field_name('type'))
            annotation = re.search(r'@(RequestBody|PathVariable|RequestParam|RequestHeader)\b(?:\(([^)]*)\))?', text(par))
            kind, options = (annotation[1], annotation[2] or '') if annotation else ('', '')
            alias = re.search(r'^\s*"([^"]+)"|\b(?:value|name)\s*=\s*"([^"]+)"', options)
            default = re.search(r'\bdefaultValue\s*=\s*"([^"]*)"', options)
            result.append({'name': name, 'type': typ, 'kind': kind,
                           'wire_name': next((v for v in alias.groups() if v is not None), name) if alias else name,
                           'required': not bool(re.search(r'\brequired\s*=\s*false\b', options)) and default is None,
                           'default': default[1] if default else U})
        return result

    def request_body_defaults(self, mid):
        """Java field defaults for known omitted JSON properties, not unknown inputs."""
        result = {}
        for parameter in self.http_parameters(mid):
            if parameter['kind'] != 'RequestBody':
                continue
            tid = self.resolve_type(parameter['type'], self.methods[mid]['module'], self.methods[mid]['file'])
            if not tid:
                continue
            if any(a['name'].split('.')[-1] == 'JsonDeserialize' for a in self.nodes[tid].get('annotations', [])):
                continue
            # Only straight constant assignments in a no-arg constructor are
            # modeled here. Executable creators still require full semantics.
            constructors = [m for m, meta in self.methods.items() if meta['owner'] == tid and meta['name'] == '<init>']
            if any('JsonCreator' in text(self.ast.get(m)) for m in constructors):
                continue
            noarg = [self.ast.get(m) for m in constructors if not self.parameters(m)]
            assigned, supported = {}, True
            for constructor in noarg:
                body = constructor.child_by_field_name('body') if constructor else None
                for statement in body.named_children if body else []:
                    if statement.type in ('line_comment', 'block_comment'):
                        continue
                    expression = statement.named_children[0] if statement.type == 'expression_statement' and statement.named_children else None
                    if expression is None or expression.type != 'assignment_expression' or text(expression.child_by_field_name('operator')) != '=':
                        supported = False
                        break
                    key = text(expression.child_by_field_name('left')).removeprefix('this.')
                    try:
                        value = json.loads(text(expression.child_by_field_name('right')))
                    except ValueError:
                        supported = False
                        break
                    if key not in self.type_fields.get(tid, {}):
                        supported = False
                        break
                    assigned[key] = value
            if not supported:
                continue
            for key, field in self.type_fields.get(tid, {}).items():
                typ = field['type']
                value = (field['default'] if field['has_initializer'] else False if typ == 'boolean'
                         else 0 if typ in ('byte', 'short', 'int', 'long', 'float', 'double')
                         else U if typ == 'char' else None)
                result[key] = assigned.get(key, value)
        return result

    def materialize(self, database, rid, row):
        resource = self.nodes[rid]
        keys = self.id_fields.get(rid, [])
        record = database.materialize(resource, row, self.column_aliases.get(rid), self.collections.get(rid), keys[0] if len(keys) == 1 else None)
        tid = self.entities.get(rid)

        def fill(owner, obj):
            for name, field in self.type_fields.get(owner, {}).items():
                target = self.resolve_type(field['type'], self.nodes[owner].get('module'))
                if field['embedded'] and target:
                    obj[name] = fill(target, {'__type__': self.nodes[target]['fqn']})
                    continue
                key = re.sub(r'_([a-z])', lambda m: m[1].upper(), field['column'])
                val = record.get(name, row.get(key, U))
                if field['type'].split('.')[-1] == 'Date' and target is None and val is not None:
                    val = date_value(val)
                if isinstance(val, list) and re.search(r'(?:List|Set|Collection)<(?:String|Integer|Long|Double)>', field['type']):
                    val = [v.get(key, U) if isinstance(v, dict) else v for v in val]
                elif isinstance(val, list):
                    element = re.fullmatch(r'(?:List|Set|Collection)<([\w.]+)>', field['type'])
                    target = self.resolve_type(element[1], self.nodes[owner].get('module'), field['file']) if element else None
                    if target in self.type_fields:
                        val = [{'__type__': self.nodes[target]['fqn'], **item} if isinstance(item, dict) and '__type__' not in item else item for item in val]
                if target in self.enum_members and val is not U:
                    members = self.enum_members[target]
                    match = next((x for x in members if x.rsplit('.', 1)[-1] == val), None) if isinstance(val, str) else members[val] if isinstance(val, int) and 0 <= val < len(members) else None
                    val = dict(self.enum_objects[match]) if match else U
                obj[name] = val
            return obj

        return fill(tid, record) if tid else record

    def parameters(self, mid):
        cache = self.__dict__.setdefault('_parameter_cache', {})
        if mid in cache:
            return list(cache[mid])
        node = self.ast.get(mid)
        pars = node.child_by_field_name('parameters') if node else None
        result = []
        for p in pars.named_children if pars else []:
            if p.type != 'formal_parameter':
                continue
            typ = text(p.child_by_field_name('type'))
            tid = self.resolve_type(typ, self.methods[mid]['module'], self.methods[mid]['file'])
            if tid and '<' not in typ and '[' not in typ:
                typ = self.nodes[tid]['fqn']
            result.append((text(p.child_by_field_name('name')), typ))
        cache[mid] = tuple(result)
        return result

    def site(self, mid, node):
        name_node = node.child_by_field_name('name')
        name = '<init>' if node.type == 'object_creation_expression' else text(name_node)
        row = (name_node or node).start_point.row + 1
        candidates = self.by_line.get((mid, row, name), [])
        if not candidates and node.type == 'object_creation_expression':
            candidates = self.by_line.get((mid, node.start_point.row + 1, name), [])
        return min(candidates, key=lambda k: abs(self.nodes[k]['col'] - (name_node or node).start_point.column - 1)) if candidates else None

    def targets(self, mid, site):
        if not site:
            return []
        edges = self.edges[site]
        targets = edges.get('runtime_dispatch') or edges.get('calls', set())
        out = set()
        for target in targets:
            if target not in self.methods:
                continue
            if not self.methods[target].get('abstract'):
                out.add(target)
            else:
                out.update(m for m in self.ix.cha(target) if not self.methods[m].get('abstract'))
        if not out:
            cs = self.nodes[site]
            owner = cs.get('receiver_type')
            for candidate in self.by_name.get(cs['callee'], []):
                meta = self.methods[candidate]
                enum_owner = (cs.get('receiver') or '').split('.')[0]
                fqn = self.nodes[meta['owner']]['fqn']
                owner_matches = fqn == owner or (not owner and fqn.split('.')[-1] == enum_owner and any(k.startswith(enum_owner + '.') for k in self.enums))
                if (not meta.get('abstract') and owner_matches
                        and len(meta.get('params_as_written', [])) == cs['arg_count']):
                    out.add(candidate)
        unit = self.ix.unit_of(mid)
        receiver = self.nodes[site].get('receiver', '')
        field = self.type_fields.get(self.methods[mid]['owner'], {}).get(receiver, {})
        qualifier = field.get('qualifier')
        if qualifier:
            selected = set()
            for m in out:
                owner = self.nodes[self.methods[m]['owner']]
                simple = owner['fqn'].split('.')[-1]
                bean_names = {simple[:1].lower() + simple[1:]}
                for annotation in owner.get('annotations', []):
                    if annotation['name'].split('.')[-1] in ('Service', 'Component', 'Repository', 'Qualifier'):
                        bean_names.update(re.findall(r'"([^"]+)"', annotation.get('args', '')))
                if qualifier in bean_names:
                    selected.add(m)
            out = selected
        return sorted(m for m in out if unit in self.ix.units.get(self.methods[m]['module'], ())
                      and self.enabled_type(self.methods[m]['owner']))

    def methods_of(self, owner, name):
        return [mid for mid in self.by_name.get(name, []) if self.methods[mid]['owner'] == owner and not self.methods[mid].get('abstract')]

    def enabled_type(self, owner):
        annotations = self.nodes[owner].get('annotations', [])
        profiles = [a for a in annotations if a['name'].split('.')[-1] == 'Profile']
        if not profiles:
            return True
        values = re.findall(r'"([^"]+)"', profiles[0].get('args', ''))
        return any((value[1:] not in self.active_profiles) if value.startswith('!') else value in self.active_profiles
                   for value in values)

    def source_targets(self, mid, node):
        """Resolve simple source calls even when a call-site edge is absent."""
        owner = self.methods[mid]['owner']
        module = self.methods[mid]['module']
        if node.type == 'object_creation_expression':
            target_type = self.resolve_type(text(node.child_by_field_name('type')), module)
            name = '<init>'
        else:
            name = text(node.child_by_field_name('name'))
            receiver = text(node.child_by_field_name('object'))
            if not receiver or receiver == 'this':
                target_type = owner
            else:
                info = self.type_fields.get(owner, {}).get(receiver)
                target_type = self.resolve_type(info['type'] if info else receiver, module)
        if not target_type:
            return []
        args = node.child_by_field_name('arguments')
        count = len([a for a in args.named_children if a.type not in ('line_comment', 'block_comment')]) if args else 0
        result = []
        for target in self.by_name.get(name, []):
            meta = self.methods[target]
            if meta['owner'] == target_type and len(meta.get('params_as_written', [])) == count:
                result.extend(self.ix.cha(target) if meta.get('abstract') else [target])
        unit = self.ix.unit_of(mid)
        return sorted(m for m in set(result) if not self.methods[m].get('abstract')
                      and unit in self.ix.units.get(self.methods[m]['module'], ())
                      and self.enabled_type(self.methods[m]['owner']))

"""Resolve response references by declared entity and explicit selection language."""
import re
from decimal import Decimal, InvalidOperation
from baseline_nlp import ntoks
from .state import U
from .project import text


def source_string(project, value):
    """Evaluate only source-proven pure toString/getter expressions for composite IDs."""
    active = set()

    def invoke(obj, tid, name):
        signature = (tid, name)
        if tid is None or signature in active:
            return U
        methods = [m for m in project.methods_of(tid, name) if not project.parameters(m)]
        if not methods:
            if name == 'name' and tid in project.enum_members and isinstance(obj, dict):
                return obj.get('__enum__', '').rsplit('.', 1)[-1] or U
            return U
        if len(methods) != 1:
            return U
        node = project.ast.get(methods[0])
        body = node.child_by_field_name('body') if node else None
        statements = [s for s in body.named_children if s.type not in ('line_comment', 'block_comment')] if body else []
        if len(statements) != 1 or statements[0].type != 'return_statement':
            return U
        active.add(signature)
        result = expression(statements[0].named_children[0], obj, tid)
        active.remove(signature)
        return result

    def expression(node, obj, tid):
        kind = node.type
        if kind == 'this':
            return obj
        if kind == 'identifier':
            return obj.get(text(node), U)
        if kind == 'field_access' and text(node.child_by_field_name('object')) == 'this':
            return obj.get(text(node.child_by_field_name('field')), U)
        if kind == 'string_literal':
            import json
            try:
                return json.loads(text(node))
            except ValueError:
                return U
        if kind == 'binary_expression' and text(node.child_by_field_name('operator')) == '+':
            left, right = expression(node.child_by_field_name('left'), obj, tid), expression(node.child_by_field_name('right'), obj, tid)
            if left is U or right is U or not isinstance(left, (str, int)) or not isinstance(right, (str, int)):
                return U
            return str(left) + str(right) if isinstance(left, str) or isinstance(right, str) else left + right
        if kind == 'method_invocation':
            args = node.child_by_field_name('arguments')
            if args and args.named_children:
                return U
            receiver = node.child_by_field_name('object')
            receiver_value = obj if receiver is None else expression(receiver, obj, tid)
            target = tid
            if receiver is not None and receiver.type == 'identifier':
                field = project.type_fields.get(tid, {}).get(text(receiver), {})
                target = project.resolve_type(field.get('type', ''), project.nodes[tid].get('module'), project.nodes[tid].get('file'))
            if not isinstance(receiver_value, dict):
                return U
            return invoke(receiver_value, target, text(node.child_by_field_name('name')))
        return U

    if not isinstance(value, dict):
        return U
    tid = project.resolve_type(value.get('__type__', ''), '')
    result = invoke(value, tid, 'toString')
    return result if isinstance(result, str) else U


def contains_unknown(value):
    if value is U:
        return True
    if isinstance(value, dict):
        return any(contains_unknown(v) for k, v in value.items() if not str(k).startswith('__') or k == '__json__')
    return isinstance(value, (list, tuple)) and any(contains_unknown(v) for v in value)


def entity_words(value):
    value = re.sub(r'(Controller|Service|Impl|Request|Response|Dto|Info|Entity)$', '', value.split('.')[-1], flags=re.I)
    return set(ntoks(value)) - {'get', 'find', 'query', 'lookup', 'read', 'create', 'new', 'id', 'key'}


def objects(value, path):
    if isinstance(value, dict):
        if value.get('__type__') and '__symbol__' not in value:
            yield path, value
        for key, child in value.items():
            if not str(key).startswith('__'):
                yield from objects(child, path + '.' + str(key))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            yield from objects(child, path + '[' + str(index) + ']')


def ordinal_for(action, requested):
    for candidate in re.finditer(r'\b(first|second|third|fourth)\b(?!-)', action, re.I):
        following = re.split(r'[,;()]|\b(?:for|with|without|on|of)\b', action[candidate.end():], 1, flags=re.I)[0]
        if requested & set(ntoks(following)[:4]):
            return candidate
    return None


def new_for(action, requested):
    for candidate in re.finditer(r'\b(?:(?:newly|just|recently)\s+(?:created|added|registered|booked)|new|latest)\b', action, re.I):
        following = re.split(r'[,;()]|\b(?:for|with|without|on|of)\b', action[candidate.end():], 1, flags=re.I)[0]
        if requested & set(ntoks(following)[:4]):
            return candidate
    return None


def cheapest_reference(action, history, by_step, observations):
    """Use the matching search and require a unique minimum in every price field."""
    if not re.search(r'\bcheapest\b', action, re.I):
        return None
    scopes = [index for index in by_step if re.search(r'\bcheapest\b', history[index].get('action', ''), re.I)]
    if not scopes:
        return None
    index = max(scopes)
    rows = [observations[index, identity] for identity in by_step[index]]
    if len(rows) == 1:
        return rows[0][:2]
    vectors = []
    for _, _, obj in rows:
        prices = {key: value for key, value in obj.items() if set(ntoks(key)) & {'price', 'cost'}}
        if not prices or any(isinstance(value, bool) or value is U or contains_unknown(value) for value in prices.values()):
            return None
        try:
            vector = {key: Decimal(str(value)) for key, value in prices.items()}
        except InvalidOperation:
            return None
        if not all(value.is_finite() for value in vector.values()):
            return None
        vectors.append(vector)
    if any(vector.keys() != vectors[0].keys() for vector in vectors):
        return None
    winners = [position for position, vector in enumerate(vectors)
               if all(all(vector[key] <= other[key] for key in vector) for other in vectors)]
    return rows[winners[0]][:2] if len(winners) == 1 else None


def history_value(project, mid, field, action, history, requested_entity=None, use_selection=True):
    """Only typed matching owners qualify. Multiple objects remain ambiguous."""
    norm = lambda value: re.sub(r'[^a-z0-9]', '', value.lower())
    requested = set(requested_entity) if requested_entity else entity_words(field[:-4] if field.endswith('Name') else field)
    if not requested:
        route_entities = set()
        names = {field, *(p['wire_name'] for p in project.http_parameters(mid) if p['name'] == field)}
        for handler, _, route in project.ix.handlers:
            if handler != mid:
                continue
            for index, segment in enumerate(route):
                if segment.strip('{}').split(':', 1)[0] in names and index > 0:
                    previous = route[index - 1]
                    if not previous.startswith('{'):
                        route_entities.add(tuple(sorted(entity_words(previous))))
        requested = set(next(iter(route_entities))) if len(route_entities) == 1 else entity_words(project.nodes[project.methods[mid]['owner']]['fqn'])
    candidates, by_step, creations, confirmed_creations, observations = {}, {}, {}, {}, {}
    for index, item in enumerate(history):
        observed = [*objects(item.get('result', U), 'history[' + str(index) + '].result'),
                    *objects(item.get('created_objects', []), 'history[' + str(index) + '].created_objects')]
        for path, obj in observed:
            owner = entity_words(obj['__type__'])
            tid = project.resolve_type(obj['__type__'], project.methods[mid]['module'])
            declared = project.type_fields.get(tid, {})
            ids = [k for k, meta in declared.items() if meta.get('id')]
            keys = [k for k in obj if norm(k) == norm(field)]
            named_reference = norm(field).endswith('id') and norm(field) != 'id' and any(k in declared for k in keys)
            if not named_reference and (not requested or not owner or not requested & owner):
                continue
            if norm(field) in ('key', 'id') and owner != requested:
                continue
            if not keys and owner == requested and (norm(field).endswith('id') or norm(field) in ('key', 'id')):
                keys = ids
            if not keys and owner == requested and field.endswith('Name') and 'name' in declared:
                from .nl_inputs import field_role, intermediate_field
                if field_role(field) is None and field != intermediate_field(project.request_fields(mid)):
                    keys = ['name']
            for key in keys:
                value = obj.get(key, U)
                if contains_unknown(value) or value is None:
                    continue
                rendered = source_string(project, value) if isinstance(value, dict) and '__symbol__' not in value else value
                canonical = rendered if rendered is not U else value
                identity = (tuple(sorted(owner)), repr(canonical))
                candidates[identity] = (path + '.' + key, value, index)
                observations[index, identity] = (path + '.' + key, value, obj)
                by_step.setdefault(index, [])
                if identity not in by_step[index]:
                    by_step[index].append(identity)
                if owner == requested and ('.created_objects' in path or re.search(r'\b(?:create|add|register|book|reserve|insert)\b', item.get('action', ''), re.I)):
                    creations.setdefault(identity, index)
                if owner == requested and '.created_objects' in path:
                    confirmed_creations[identity] = index
    identities = list(candidates)
    ordinal = ordinal_for(action, requested)
    wants_new = new_for(action, requested)
    cheapest = cheapest_reference(action, history, by_step, observations) if not ordinal and not wants_new else None
    if cheapest:
        return cheapest
    if use_selection and not ordinal and not wants_new and (norm(field).endswith('id') or norm(field) in ('key', 'id')):
        definite = any(requested <= set(ntoks(re.split(r'[,;()]|\b(?:for|with|without|on)\b', action[match.end():], 1, flags=re.I)[0])[:4])
                       for match in re.finditer(r'\b(?:the|this|same)\b', action, re.I))
        latest_creation = max(confirmed_creations.values(), default=-1) if definite else -1
        for index in range(len(history) - 1, -1, -1):
            if index < latest_creation:
                break
            selected = history[index].get('selected_objects', [])
            for position, item in enumerate(selected if isinstance(selected, list) else []):
                if item.get('entity') == sorted(requested) and item.get('value', U) is not U and not contains_unknown(item['value']):
                    return 'history[' + str(index) + '].selected_objects[' + str(position) + '].value', item['value']
        if definite and confirmed_creations:
            latest = max(confirmed_creations.values())
            created = [identity for identity, index in confirmed_creations.items() if index == latest]
            if len(created) == 1:
                return candidates[created[0]][:2]
    if wants_new:
        created = [key for key in identities if key in creations]
        if not created:
            return None
        newest = max(creations[key] for key in created)
        identities = sorted(created, key=lambda key: creations[key]) if ordinal else [key for key in created if creations[key] == newest]
    elif ordinal:
        # Use the latest collection's actual order, even after later single-object reads.
        collections = [keys for keys in by_step.values() if len(keys) > 1]
        if collections:
            identities = collections[-1]
    values = [candidates[key] for key in identities]
    if ordinal and values:
        ordered = values
        position = ('first', 'second', 'third', 'fourth').index(ordinal[1].lower())
        return ordered[position][:2] if position < len(ordered) else None
    if len(values) == 1:
        return values[0][:2]
    return None


def selected_field(project, field, params, history):
    """A value from a selected object needs a matching identifier in this request."""
    for index in range(len(history) - 1, -1, -1):
        selected = history[index].get('selected_objects', [])
        for position, item in enumerate(selected if isinstance(selected, list) else []):
            obj = item.get('object', {})
            tid = project.resolve_type(obj.get('__type__', ''), '') if isinstance(obj, dict) else None
            if field not in project.type_fields.get(tid, {}):
                continue
            linked = any(entity_words(key) == set(item.get('entity', [])) and value == item.get('value') for key, value in params.items())
            value = obj.get(field, U)
            if linked and value is not U and not contains_unknown(value):
                return 'history[' + str(index) + '].selected_objects[' + str(position) + '].object.' + field, value
    return None


def history_role_value(project, field, params, history):
    """Carry role values only from an object whose declared ID matches this request."""
    from .nl_inputs import field_role
    role = field_role(field)
    if role not in ('origin', 'destination', 'via') and field.lower() != 'date':
        return None
    identifiers = {key: value for key, value in params.items()
                   if key.lower().endswith('id') and value is not U and value is not None}
    if not identifiers:
        return None
    for index in range(len(history) - 1, -1, -1):
        previous = history[index].get('parameters', {})
        shared = identifiers.keys() & previous.keys()
        if shared and all(previous[key] == identifiers[key] for key in shared):
            values = [(key, value) for key, value in previous.items() if field_role(key) == role
                      and value is not None and value is not U and not contains_unknown(value)]
            if len({repr(value) for _, value in values}) == 1:
                return 'history[' + str(index) + '].parameters.' + values[0][0], values[0][1]
        matches = []
        for path, obj in objects(history[index].get('result', U), 'history[' + str(index) + '].result'):
            tid = project.resolve_type(obj['__type__'], '')
            declared = project.type_fields.get(tid, {})
            linked = False
            for key, expected in identifiers.items():
                value = obj.get(key, U) if key in declared else U
                if isinstance(value, dict) and '__symbol__' not in value:
                    value = source_string(project, value)
                if value is not U and value == expected:
                    linked = True
            if not linked:
                continue
            if field.lower() == 'date':
                filters = [(key, value) for key, value in previous.items() if field_role(key) == 'date'
                           and value is not None and value is not U and not contains_unknown(value)]
                if len({repr(value) for _, value in filters}) == 1:
                    return 'history[' + str(index) + '].parameters.' + filters[0][0], filters[0][1]
            for key in declared:
                value = obj.get(key, U)
                if field_role(key) == role and value is not U and value is not None and not contains_unknown(value):
                    matches.append((path + '.' + key, value))
        if matches:
            return matches[0] if len({repr(value) for _, value in matches}) == 1 else None
    return None

"""Bounded abstract interpretation of Java source, with explicit unknown values.

Only source text is interpreted. This module never loads JVM classes or contacts
the application's services. Unresolved branches retain both possible paths.
"""
from collections import defaultdict
from copy import deepcopy
import json
import operator
import re
from urllib.parse import urlsplit, parse_qsl, unquote

from .project import text
from .state import U
from .models import construct, library, known, unwrap, wire, key_equal, http_entity, optional_value
from .constraints import assume, compare


def member(obj, key):
    if not isinstance(obj, dict):
        return U
    if key in obj:
        return obj[key]
    normalized = re.sub(r'[^a-z0-9]', '', key.lower())
    return next((v for k, v in obj.items() if re.sub(r'[^a-z0-9]', '', k.lower()) == normalized), U)


def merge(a, b):
    if a == b:
        return a
    if isinstance(a, dict) and isinstance(b, dict):
        return {key: merge(a.get(key, U), b.get(key, U)) for key in sorted(a.keys() | b.keys(), key=lambda k: (type(k).__name__, str(k)))}
    return U


class AlternativeRequired(Exception):
    def __init__(self, key, choices):
        self.key, self.choices = key, choices


class JavaThrow(Exception):
    def __init__(self, value):
        self.value = value


class Engine:
    def __init__(self, project, state, decisions=None, conservative=False, constraints=True):
        self.p, self.state = project, state
        self.edges = set()
        self.evidence = defaultdict(set)
        self.conditions, self.warnings = [], set()
        self.data_operations = []
        self.created_objects = []
        self.active = set()
        self.calls = 0
        self.method = None
        self.params = {}
        self.uncertain = 0
        self.decisions = decisions or {}
        self.conservative = conservative
        self.branch_index = 0
        self.approximate = False
        self.outcome = 'returned' 
        self.use_constraints = constraints
        self.variable_types = {}
        self.constraint_sequence = 0

    def constraint_symbol(self):
        self.constraint_sequence += 1
        return 'path-scalar-' + str(self.constraint_sequence)

    def choose(self, label, choices):
        self.branch_index += 1
        key = str(self.branch_index) + ':' + label
        if key in self.decisions:
            return self.decisions[key]
        if not self.conservative:
            raise AlternativeRequired(key, choices)
        self.approximate = True
        self.warnings.add('path budget: alternatives conservatively retained at ' + label)
        return None

    def add(self, source, relation, target, reason):
        self.edges.add((source, relation, target))
        self.evidence[(source, relation, target)].add(reason)

    def executed(self, mid, reason):
        self.add('', 'executes', mid, reason)

    def run(self, entry, params):
        self.params = params
        self.entry = entry
        try:
            for mid in self.p.by_name.get('doFilterInternal', []):
                if (self.p.ix.unit_of(mid) == self.p.ix.unit_of(entry)
                        and 'OncePerRequestFilter' in (self.p.root / self.p.methods[mid]['file']).read_text()):
                    self.invoke(mid, [], reason='project request filter')
            args = [self.input_value(name, typ, params) for name, typ in self.p.parameters(entry)]
            result = self.invoke(entry, args, reason='scenario request')
        except JavaThrow:
            self.outcome = 'uncaught application exception'
            return U
        return unwrap(result)

    def input_value(self, name, typ, params):
        if name.lower() in ('headers', 'httpheaders'):
            return {'__type__': 'HttpHeaders'}
        if name in params:
            if isinstance(params[name], dict) and '__json__' in params[name] and any(
                    p['name'] == name and p['kind'] == 'RequestBody' and p['type'].split('.')[-1] == 'String'
                    for p in self.p.http_parameters(self.method or getattr(self, 'entry', ''))):
                return deepcopy(params[name])
            return self.coerce(params[name], typ)
        if typ.split('.')[-1] in ('String', 'UUID', 'int', 'double', 'boolean', 'Date', 'Long'):
            return U
        value = {'__type__': typ, **deepcopy(params)}
        method = self.method or getattr(self, 'entry', '')
        meta = self.p.methods.get(method, {})
        tid = self.p.resolve_type(typ, meta.get('module'), meta.get('file'))
        if tid in self.p.type_fields and not typ.startswith('org.springframework.http.'):
            value['__http_entity__'] = False
        return value

    @staticmethod
    def coerce(value, typ):
        typ = typ.split('.')[-1]
        if value is U or value is None:
            return value
        if isinstance(value, dict) and '__symbol__' in value:
            aliases = {'Integer': 'int', 'Long': 'long', 'Boolean': 'boolean', 'Double': 'double', 'Float': 'float'}
            source_type = value['__type__'].split('.')[-1]
            return value if aliases.get(source_type, source_type) == aliases.get(typ, typ) else U
        if typ in ('boolean', 'Boolean'):
            return value if isinstance(value, bool) else value.lower() == 'true' if isinstance(value, str) and value.lower() in ('true', 'false') else U
        if typ in ('int', 'Integer', 'long', 'Long', 'short', 'Short', 'byte', 'Byte'):
            if isinstance(value, bool):
                return U
            try:
                return int(value) if isinstance(value, (str, int)) else U
            except ValueError:
                return U
        if typ in ('double', 'Double', 'float', 'Float'):
            try:
                return float(value) if not isinstance(value, bool) else U
            except (TypeError, ValueError):
                return U
        if typ == 'Date':
            from .models import date_value
            return date_value(value)
        if typ == 'String':
            return value if isinstance(value, str) else U
        if isinstance(value, str):
            try:
                if typ in ('int', 'Integer', 'long', 'Long'): return int(value)
                if typ in ('double', 'Double', 'float', 'Float'): return float(value)
                if typ in ('boolean', 'Boolean'): return value.lower() == 'true'
            except ValueError:
                return U
        return value

    def invoke(self, mid, args, receiver=None, reason='source call'):
        self.executed(mid, reason)
        if any(a['name'].split('.')[-1] == 'Transactional' for a in self.p.methods[mid].get('annotations', [])):
            self.approximate = True
            self.warnings.add('transaction dirty checking is not fully modeled: ' + mid)
        signature = (mid, json.dumps(args, sort_keys=True, default=str))
        if signature in self.active or self.calls >= 12000 or len(self.active) >= 64:
            self.warnings.add('recursion or context budget: conservative closure used')
            self.fallback(mid)
            return U
        node = self.p.ast.get(mid)
        if node is None:
            self.warnings.add('no source body: ' + mid)
            self.fallback(mid)
            return U
        self.calls += 1
        self.active.add(signature)
        previous = self.method
        previous_types = self.variable_types
        self.method = mid
        self.variable_types = dict(self.p.parameters(mid))
        env = {name: args[i] if i < len(args) else U for i, (name, _) in enumerate(self.p.parameters(mid))}
        env['this'] = receiver if isinstance(receiver, dict) else {}
        body = node.child_by_field_name('body')
        try:
            try:
                result, control = self.execute(body, env)
            except (TypeError, ValueError, IndexError, KeyError, AttributeError, ZeroDivisionError) as exc:
                self.approximate = True
                self.warnings.add('unsupported value operation in ' + mid + ': ' + type(exc).__name__)
                self.fallback(mid)
                result, control = U, None
        finally:
            self.method = previous
            self.variable_types = previous_types
            self.active.remove(signature)
        if control == 'throw':
            raise JavaThrow(result)
        return result

    def fallback(self, mid):
        self.approximate = True
        methods, calls, remote, data = self.p.ix.closure({mid})
        for method in methods:
            self.executed(method, 'unresolved source: may-call closure')
        for relation, pairs in [('calls', calls), ('remote', remote), ('data', data)]:
            for source, target in pairs:
                self.add(source, relation, target, 'unresolved source: may-call closure')
                if relation == 'data':
                    rows = self.state.database.rows(self.p.nodes[target])
                    if rows is not None:
                        self.state.database.invalidate(rows)

    def execute(self, node, env):
        if node is None:
            return U, None
        typ = node.type
        if typ in ('block', 'constructor_body'):
            for child in node.named_children:
                value, control = self.execute(child, env)
                if control:
                    return value, control
            return U, None
        if typ in ('return_statement', 'throw_statement'):
            value = self.value(node.named_children[0], env) if node.named_children else None
            return value, 'return' if typ == 'return_statement' else 'throw'
        if typ == 'if_statement':
            cond = self.value(node.child_by_field_name('condition'), env)
            self.conditions.append({'method': self.method, 'line': node.start_point.row + 1,
                                    'condition': text(node.child_by_field_name('condition')),
                                    'value': cond if isinstance(cond, bool) else 'unknown'})
            if isinstance(cond, bool):
                return self.execute(node.child_by_field_name('consequence' if cond else 'alternative'), env)
            decision = self.choose(self.method + ':' + str(node.start_point.row + 1), [True, False])
            if decision is not None:
                if self.use_constraints:
                    refined = assume(node.child_by_field_name('condition'), env, decision,
                                     self.variable_types, self.constraint_symbol)
                    self.conditions[-1]['refined'] = refined
                return self.execute(node.child_by_field_name('consequence' if decision else 'alternative'), env)
            before_state = deepcopy(self.state)
            left, right = deepcopy(env), deepcopy(env)
            self.uncertain += 1
            self.state = deepcopy(before_state)
            a, ac = self.execute(node.child_by_field_name('consequence'), left)
            left_state = self.state
            self.state = deepcopy(before_state)
            b, bc = self.execute(node.child_by_field_name('alternative'), right)
            right_state = self.state
            self.state = before_state
            # Changes on incompatible paths are not committed to a shared database.
            self.state.database.unknown_tables.update(left_state.database.unknown_tables | right_state.database.unknown_tables)
            for table in set(left_state.database.tables) | set(right_state.database.tables):
                if left_state.database.tables.get(table) != right_state.database.tables.get(table):
                    self.state.database.unknown_tables.add(table)
            self.uncertain -= 1
            env.update(merge(left, right))
            return (merge(a, b), ac) if ac == bc and ac else (U, None)
        if typ == 'enhanced_for_statement':
            values = self.value(node.child_by_field_name('value'), env)
            name = text(node.child_by_field_name('name'))
            items = values if isinstance(values, list) else [U]
            if len(items) > 64:
                self.approximate = True
                self.warnings.add('loop collection widened after 64 elements')
                items = items[:64] + [U]
            for item in items:
                env[name] = item
                result, control = self.execute(node.child_by_field_name('body'), env)
                if control in ('return', 'throw') and isinstance(values, list):
                    return result, control
                if control == 'break': break
            return U, None
        if typ in ('for_statement', 'while_statement', 'do_statement'):
            init = node.child_by_field_name('init')
            if init: self.execute(init, env)
            condnode = node.child_by_field_name('condition')
            for iteration in range(64):
                cond = self.value(condnode, env) if condnode else U
                if cond is False and not (typ == 'do_statement' and iteration == 0): break
                if cond is U:
                    decision = self.choose(self.method + ':loop:' + str(node.start_point.row + 1), [True, False])
                    if decision is False:
                        break
                    if decision is True:
                        cond = True
                    else:
                        self.uncertain += 1
                result, control = self.execute(node.child_by_field_name('body'), env)
                if cond is U: self.uncertain -= 1
                if control in ('return', 'throw') and cond is True: return result, control
                if control == 'break': break
                update = node.child_by_field_name('update')
                if update: self.value(update, env)
                if cond is not True:
                    self.warnings.add('unknown loop bounded to one pass: ' + self.method)
                    break
            else:
                self.approximate = True
                self.warnings.add('loop bounded after 64 passes: ' + self.method)
                self.fallback(self.method)
            return U, None
        if typ == 'try_statement' or typ == 'try_with_resources_statement':
            resources = node.child_by_field_name('resources')
            if resources:
                self.value(resources, env)
            try:
                result, control = self.execute(node.child_by_field_name('body'), env)
            except JavaThrow as exc:
                result, control = exc.value, 'throw'
            if control == 'throw':
                for child in node.named_children:
                    if child.type == 'catch_clause':
                        result, control = self.execute(child.child_by_field_name('body'), env)
                        break
